import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as d,af as r}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"阿里云百炼速查表","description":"查地域、Key、Base URL、套餐对照。模型全表和单价只链官方页。","frontmatter":{"title":"阿里云百炼速查表","description":"查地域、Key、Base URL、套餐对照。模型全表和单价只链官方页。","domain":"product","tags":["model-platform"],"role":"cheatsheet"},"headers":[],"relativePath":"zh/products/bailian/bailian-cheatsheet.md","filePath":"zh/products/bailian/bailian-cheatsheet.md","lastUpdated":1787110548000}'),o={name:"zh/products/bailian/bailian-cheatsheet.md"};function l(n,t,i,h,s,c){return d(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="阿里云百炼速查表" tabindex="-1">阿里云百炼速查表 <a class="header-anchor" href="#阿里云百炼速查表" aria-label="Permalink to &quot;阿里云百炼速查表&quot;">​</a></h1><blockquote><p>查阅用。学习走 <a href="./index.html">地图</a> 和 <a href="./bailian.html">教程</a>。概念走 <a href="./bailian-glossary.html">术语表</a>。</p></blockquote><p><strong>最后核实：2026-08-19。</strong> 模型 ID、套餐价、主机名以当时打开的官方页为准。</p><h2 id="选哪条路" tabindex="-1">选哪条路 <a class="header-anchor" href="#选哪条路" aria-label="Permalink to &quot;选哪条路&quot;">​</a></h2><table tabindex="0"><thead><tr><th>我要做的事</th><th>用</th><th>官方页</th></tr></thead><tbody><tr><td>自己的服务里调模型</td><td>按量 API + OpenAI 兼容</td><td><a href="https://help.aliyun.com/zh/model-studio/first-api-call-to-qwen" target="_blank" rel="noreferrer">首次调用</a></td></tr><tr><td>编程工具里包月用模型</td><td>Token Plan（官方推荐新订）或 Coding Plan</td><td><a href="https://help.aliyun.com/zh/model-studio/token-plan-overview" target="_blank" rel="noreferrer">Token Plan</a>、<a href="https://help.aliyun.com/zh/model-studio/coding-plan" target="_blank" rel="noreferrer">Coding Plan</a></td></tr><tr><td>无代码问答 / 智能体</td><td>控制台应用，优先 Agent 2.0</td><td><a href="https://help.aliyun.com/zh/model-studio/new-single-agent-application" target="_blank" rel="noreferrer">Agent 2.0</a></td></tr><tr><td>本机 Agent 调度多模态能力</td><td>百炼 CLI <code>bl</code></td><td><a href="https://bailian.aliyun.com/cli/install.md" target="_blank" rel="noreferrer">安装说明</a></td></tr><tr><td>只聊天</td><td>通义千问（#83）</td><td>不是百炼</td></tr><tr><td>阿里云编码 IDE</td><td>Qoder CN / 灵码（#84）</td><td><a href="https://help.aliyun.com/zh/model-studio/lingma-agent" target="_blank" rel="noreferrer">接入说明</a></td></tr></tbody></table><h2 id="地域" tabindex="-1">地域 <a class="header-anchor" href="#地域" aria-label="Permalink to &quot;地域&quot;">​</a></h2><p>中国站产品简介（2026-08-19）：华北 2（北京）、美国（弗吉尼亚）、新加坡、德国（法兰克福）、日本（东京）。</p><table tabindex="0"><thead><tr><th>事实</th><th>出处</th></tr></thead><tbody><tr><td>Key、Endpoint、模型、功能、价格按地域隔离</td><td><a href="https://help.aliyun.com/zh/model-studio/what-is-model-studio" target="_blank" rel="noreferrer">产品简介</a></td></tr><tr><td>中国站新人免费额度只在北京</td><td><a href="https://help.aliyun.com/zh/model-studio/new-free-quota" target="_blank" rel="noreferrer">新人免费额度</a></td></tr><tr><td>国际站简介把免费额度写在新加坡</td><td><a href="https://www.alibabacloud.com/help/en/model-studio/what-is-model-studio" target="_blank" rel="noreferrer">What is Model Studio</a></td></tr><tr><td>Token Plan 目前仅北京</td><td><a href="https://help.aliyun.com/zh/model-studio/token-plan-overview" target="_blank" rel="noreferrer">Token Plan</a></td></tr><tr><td>国际站侧栏还出现中国（香港）</td><td>国际站简介；中国站简介未列。用哪一站就认哪一站</td></tr></tbody></table><p>开通后不支持关闭服务。停调用 = 删 Key。<a href="https://help.aliyun.com/zh/model-studio/faq-about-alibaba-cloud-model-studio" target="_blank" rel="noreferrer">FAQ</a></p><h2 id="api-key" tabindex="-1">API Key <a class="header-anchor" href="#api-key" aria-label="Permalink to &quot;API Key&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>官方值</th></tr></thead><tbody><tr><td>环境变量</td><td><code>DASHSCOPE_API_KEY</code></td></tr><tr><td>按量（升级后新建）</td><td><code>sk-ws</code> 开头，只展示一次</td></tr><tr><td>按量（升级前）</td><td><code>sk-</code> 开头，仍可用</td></tr><tr><td>Coding Plan / Token Plan 专属</td><td><code>sk-sp-</code></td></tr><tr><td>北京 / 新加坡 / 东京 / 法兰克福</td><td>每主账号每地域最多 50 个</td></tr><tr><td>美国（弗吉尼亚）</td><td>每归属账号最多 20 个；无禁用/重置</td></tr><tr><td>有效期</td><td>无过期；删除即失效</td></tr><tr><td>子账号被删</td><td>其创建的 Key 全部失效</td></tr></tbody></table><p>来源：<a href="https://help.aliyun.com/zh/model-studio/get-api-key" target="_blank" rel="noreferrer">获取 API Key</a>。</p><h2 id="base-url" tabindex="-1">Base URL <a class="header-anchor" href="#base-url" aria-label="Permalink to &quot;Base URL&quot;">​</a></h2><p>把 <code>{WorkspaceId}</code> 换成控制台里的业务空间 ID。</p><table tabindex="0"><thead><tr><th>地域</th><th>OpenAI 兼容（模型清单 / 首次调用）</th><th>Anthropic 兼容（模型清单）</th></tr></thead><tbody><tr><td>华北 2（北京）</td><td><code>https://{WorkspaceId}.cn-beijing.maas.aliyuncs.com/compatible-mode/v1</code></td><td><code>https://{WorkspaceId}.cn-beijing.maas.aliyuncs.com/apps/anthropic</code></td></tr><tr><td>新加坡</td><td><code>https://{WorkspaceId}.ap-southeast-1.maas.aliyuncs.com/compatible-mode/v1</code></td><td><code>https://{WorkspaceId}.ap-southeast-1.maas.aliyuncs.com/apps/anthropic</code></td></tr><tr><td>日本（东京）</td><td><code>https://{WorkspaceId}.ap-northeast-1.maas.aliyuncs.com/compatible-mode/v1</code></td><td><code>https://{WorkspaceId}.ap-northeast-1.maas.aliyuncs.com/apps/anthropic</code></td></tr><tr><td>德国（法兰克福）</td><td><code>https://{WorkspaceId}.eu-central-1.maas.aliyuncs.com/compatible-mode/v1</code></td><td><code>https://{WorkspaceId}.eu-central-1.maas.aliyuncs.com/apps/anthropic</code></td></tr><tr><td>美国（弗吉尼亚）</td><td><code>https://dashscope-us.aliyuncs.com/compatible-mode/v1</code>（<a href="https://help.aliyun.com/zh/model-studio/models" target="_blank" rel="noreferrer">模型清单</a>）</td><td><code>https://dashscope-us.aliyuncs.com/apps/anthropic</code></td></tr></tbody></table><p>DashScope 原生主机把路径换成 <code>/api/v1</code>，见同一张模型清单。</p><p><strong>两份官方页不一致，写在这里避免各抄各的：</strong></p><ul><li>产品简介的美国示例仍出现 <code>{WorkspaceId}.us-east-1.maas.aliyuncs.com</code>。本表美国行跟<strong>模型清单</strong>。</li><li>Coding Plan 页把按量 OpenAI 主机写成 <code>https://dashscope.aliyuncs.com/compatible-mode/v1</code>。新代码跟<strong>首次调用 / 模型清单</strong>。</li></ul><p>Coding Plan 专属：</p><ul><li>OpenAI：<code>https://coding.dashscope.aliyuncs.com/v1</code></li><li>Anthropic：<code>https://coding.dashscope.aliyuncs.com/apps/anthropic</code></li></ul><p>Token Plan 专属主机以控制台为准，不要复用上表 Coding Plan 行。</p><h2 id="模型怎么查" tabindex="-1">模型怎么查 <a class="header-anchor" href="#模型怎么查" aria-label="Permalink to &quot;模型怎么查&quot;">​</a></h2><p>禁止在本站维护一份「当前全量模型表」。打开：</p><ul><li><a href="https://help.aliyun.com/zh/model-studio/models" target="_blank" rel="noreferrer">选择模型</a></li><li><a href="https://help.aliyun.com/zh/model-studio/model-pricing" target="_blank" rel="noreferrer">模型调用价格</a></li></ul><p>产品简介的档位：Max = 最强；Plus = 多数场景推荐；Flash = 低延迟。2026-08 简介点名最新旗舰 <code>qwen3.8-max</code>。首次调用示例用的是 <code>qwen-plus</code>。</p><p>FAQ：<code>qwen-plus-latest</code> 属于 Qwen3 系列，<strong>不是</strong> Qwen3.5 / Qwen3.7 的别名。Qwen3.5、Qwen3.7 是并列系列。</p><h2 id="套餐对照-数字会变-下单页优先" tabindex="-1">套餐对照（数字会变，下单页优先） <a class="header-anchor" href="#套餐对照-数字会变-下单页优先" aria-label="Permalink to &quot;套餐对照（数字会变，下单页优先）&quot;">​</a></h2><p>核实日打开的 <a href="https://help.aliyun.com/zh/model-studio/token-plan-overview" target="_blank" rel="noreferrer">Token Plan 概述</a> 与 <a href="https://help.aliyun.com/zh/model-studio/coding-plan" target="_blank" rel="noreferrer">Coding Plan 概述</a>：</p><table tabindex="0"><thead><tr><th></th><th>Token Plan 个人版</th><th>Token Plan 团队版</th><th>Coding Plan Pro</th></tr></thead><tbody><tr><td>计量</td><td>Credits，7 天窗口</td><td>Credits / 座席 / 月</td><td>请求次数（5 小时 / 周 / 月三档封顶，先到先停）</td></tr><tr><td>2026-08-19 页上标价</td><td>Lite 限时 39 元/月（原价 60）；Standard 139（180）；Pro 499（600）</td><td>标准座席限时 150 元/座席/月（198）；高级 550（698）；尊享 1,398</td><td>200 元/月；官方写过首月 39.90，以下单页为准</td></tr><tr><td>地域</td><td>仅北京</td><td>仅北京</td><td>见该页</td></tr><tr><td>数据训练</td><td>个人版<strong>会</strong>用于服务改进（产品简介「重要」）</td><td>团队版承诺不用于训练</td><td><strong>会</strong>用于服务改进与模型优化</td></tr><tr><td>退款</td><td>以该页 / 协议为准</td><td>以该页 / 协议为准</td><td>官方写<strong>不支持退款</strong></td></tr><tr><td>现状</td><td>官方推荐新订</td><td>多席位</td><td>Lite 2026-03-20 停新购，2026-04-13 停续费；Pro 限量</td></tr></tbody></table><p>Coding Plan Pro 页上的用量封顶（核实日）：每 5 小时 6,000 次、每周 45,000、每月 90,000。简单任务约 5–10 次，复杂约 10–30+ 次。</p><p>抵扣顺序（按量实时推理）：新人免费额度 &gt; 资源包 &gt; 节省计划 &gt; 账户余额。<a href="https://help.aliyun.com/zh/model-studio/new-free-quota" target="_blank" rel="noreferrer">新人免费额度</a>、<a href="https://help.aliyun.com/zh/model-studio/billing-for-model-studio" target="_blank" rel="noreferrer">计费项</a></p><p>Batch 为实时价的 50%，且<strong>不能</strong>用免费额度 / 节省计划 / 资源包。<a href="https://help.aliyun.com/zh/model-studio/billing-for-model-studio" target="_blank" rel="noreferrer">计费项</a></p><p>万相会员不能抵扣百炼 API。<a href="https://help.aliyun.com/zh/model-studio/faq-about-alibaba-cloud-model-studio" target="_blank" rel="noreferrer">FAQ</a></p><h2 id="百炼-cli" tabindex="-1">百炼 CLI <a class="header-anchor" href="#百炼-cli" aria-label="Permalink to &quot;百炼 CLI&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>官方值</th></tr></thead><tbody><tr><td>npm 包</td><td><code>bailian-cli</code></td></tr><tr><td>命令</td><td><code>bl</code>、<code>bailian</code></td></tr><tr><td>Node</td><td>≥ 22.12.0</td></tr><tr><td>安装</td><td><code>npm install -g bailian-cli</code>（不要用 pnpm / yarn 装这个包）</td></tr><tr><td>登录</td><td><code>bl auth login --console</code></td></tr><tr><td>验活</td><td><code>bl text chat --message &quot;ping&quot; --non-interactive --output json</code></td></tr><tr><td>地域开关</td><td><code>--region cn|us|intl</code>，默认 <code>cn</code></td></tr></tbody></table><p>不是 <code>aliyun bailian</code>。</p><h2 id="术语索引" tabindex="-1">术语索引 <a class="header-anchor" href="#术语索引" aria-label="Permalink to &quot;术语索引&quot;">​</a></h2><p>一行一个，解释在术语表。</p><table tabindex="0"><thead><tr><th>术语</th><th>钩子</th></tr></thead><tbody><tr><td><a href="./bailian-glossary.html#百炼-model-studio">百炼 / Model Studio</a></td><td>平台，不是聊天窗口</td></tr><tr><td><a href="./bailian-glossary.html#千问-qwen">千问</a></td><td>模型，也是另一款产品</td></tr><tr><td><a href="./bailian-glossary.html#灵码--qoder-cn">灵码 / Qoder CN</a></td><td>IDE</td></tr><tr><td><a href="./bailian-glossary.html#dashscope">DashScope</a></td><td>旧接口品牌；变量名还在</td></tr><tr><td><a href="./bailian-glossary.html#业务空间-workspace">业务空间</a></td><td>隔离权限和账单</td></tr><tr><td><a href="./bailian-glossary.html#三种调用协议">三种协议</a></td><td>OpenAI / Anthropic / DashScope</td></tr><tr><td><a href="./bailian-glossary.html#token-plan-vs-coding-plan">Token Plan vs Coding Plan</a></td><td>两套不能迁移的订阅</td></tr><tr><td><a href="./bailian-glossary.html#agent-10-vs-20">Agent 1.0 vs 2.0</a></td><td>不能升级，只能新建</td></tr><tr><td><a href="./bailian-glossary.html#百炼-cli-vs-阿里云-cli">百炼 CLI vs 阿里云 CLI</a></td><td><code>bl</code> ≠ <code>aliyun bailian</code></td></tr></tbody></table><h2 id="高质量信息源" tabindex="-1">高质量信息源 <a class="header-anchor" href="#高质量信息源" aria-label="Permalink to &quot;高质量信息源&quot;">​</a></h2><p><strong>最后一次系统性核实：2026-08-19。</strong></p><h3 id="s-级-官方唯一真相源" tabindex="-1">S 级：官方唯一真相源 <a class="header-anchor" href="#s-级-官方唯一真相源" aria-label="Permalink to &quot;S 级：官方唯一真相源&quot;">​</a></h3><table tabindex="0"><thead><tr><th>来源</th><th>用途</th></tr></thead><tbody><tr><td><a href="https://help.aliyun.com/zh/model-studio/what-is-model-studio" target="_blank" rel="noreferrer">什么是阿里云百炼</a></td><td>产品定义、地域、计费边界</td></tr><tr><td><a href="https://help.aliyun.com/zh/model-studio/models" target="_blank" rel="noreferrer">选择模型</a></td><td>模型 ID、地域、三种 Base URL</td></tr><tr><td><a href="https://help.aliyun.com/zh/model-studio/first-api-call-to-qwen" target="_blank" rel="noreferrer">首次调用</a></td><td>开通、示例代码</td></tr><tr><td><a href="https://help.aliyun.com/zh/model-studio/get-api-key" target="_blank" rel="noreferrer">获取 API Key</a></td><td>Key 格式、限额、环境变量</td></tr><tr><td><a href="https://help.aliyun.com/zh/model-studio/billing-for-model-studio" target="_blank" rel="noreferrer">计费项</a></td><td>推理 / 训练 / 部署</td></tr><tr><td><a href="https://help.aliyun.com/zh/model-studio/model-pricing" target="_blank" rel="noreferrer">模型调用价格</a></td><td>单价</td></tr><tr><td><a href="https://help.aliyun.com/zh/model-studio/new-free-quota" target="_blank" rel="noreferrer">新人免费额度</a></td><td>90 天、用完即停</td></tr><tr><td><a href="https://help.aliyun.com/zh/model-studio/token-plan-overview" target="_blank" rel="noreferrer">Token Plan</a></td><td>Credits 套餐</td></tr><tr><td><a href="https://help.aliyun.com/zh/model-studio/coding-plan" target="_blank" rel="noreferrer">Coding Plan</a></td><td>请求次套餐、专属 URL</td></tr><tr><td><a href="https://help.aliyun.com/zh/model-studio/use-chat-client-or-development-tool/" target="_blank" rel="noreferrer">接入客户端</a></td><td>第三方工具</td></tr><tr><td><a href="https://bailian.aliyun.com/cli/install.md" target="_blank" rel="noreferrer">CLI 安装说明</a></td><td><code>bailian-cli</code> 命令</td></tr><tr><td><a href="https://help.aliyun.com/zh/model-studio/faq-about-alibaba-cloud-model-studio" target="_blank" rel="noreferrer">FAQ</a></td><td>开通/关闭/千问区别</td></tr></tbody></table><h3 id="a-级-官方但偏营销或更新慢" tabindex="-1">A 级：官方但偏营销或更新慢 <a class="header-anchor" href="#a-级-官方但偏营销或更新慢" aria-label="Permalink to &quot;A 级：官方但偏营销或更新慢&quot;">​</a></h3><table tabindex="0"><thead><tr><th>来源</th><th>用途</th></tr></thead><tbody><tr><td><a href="https://www.aliyun.com/product/bailian" target="_blank" rel="noreferrer">产品落地页</a></td><td>能力宣传；数字以帮助文档为准</td></tr><tr><td><a href="https://www.alibabacloud.com/help/en/model-studio/what-is-model-studio" target="_blank" rel="noreferrer">国际站简介</a></td><td>国际地域与侧栏家族</td></tr><tr><td><a href="https://bailian.console.aliyun.com/" target="_blank" rel="noreferrer">控制台</a></td><td>实际开通与额度</td></tr><tr><td><a href="https://bailian.console.aliyun.com/cli" target="_blank" rel="noreferrer">CLI 落地页</a></td><td>CLI 能力介绍</td></tr><tr><td><a href="https://help.aliyun.com/zh/model-studio/privacy-notice" target="_blank" rel="noreferrer">合规与隐私</a></td><td>与套餐页对照数据用途</td></tr><tr><td><a href="https://terms.alicdn.com/legal-agreement/terms/common_platform_service/20230728213935489/20230728213935489.html" target="_blank" rel="noreferrer">服务协议</a></td><td>第 5.2 条（Coding Plan 点名）</td></tr></tbody></table><h3 id="b-级-需交叉验证" tabindex="-1">B 级：需交叉验证 <a class="header-anchor" href="#b-级-需交叉验证" aria-label="Permalink to &quot;B 级：需交叉验证&quot;">​</a></h3><p>开发者社区文章、第三方博客。模型 ID 和 Base URL 过期极快，只当线索，命令以 S 级为准。</p><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./index.html">学习地图</a></li><li><a href="./bailian.html">教程</a></li><li><a href="./bailian-cookbook.html">Cookbook</a></li><li><a href="./bailian-glossary.html">术语表</a></li></ul>',49)])])}const g=e(o,[["render",l]]);export{f as __pageData,g as default};
